import{_ as t,o as e,c as r,ag as d}from"./chunks/framework.D7Pdja0E.js";const u=JSON.parse('{"title":"보관함","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/archives.md","filePath":"04-org-admin-guide/archives.md","lastUpdated":1776993543000}'),i={name:"04-org-admin-guide/archives.md"};function o(l,a,h,n,s,c){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="보관함" tabindex="-1">보관함 <a class="header-anchor" href="#보관함" aria-label="Permalink to &quot;보관함&quot;">​</a></h1><p>보관 또는 삭제된 프로젝트, 토픽, 채널을 관리합니다. 보관된 항목은 읽기 전용으로 조회할 수 있으며, 필요 시 복원하거나 영구 삭제할 수 있습니다.</p><h2 id="보관함-접근" tabindex="-1">보관함 접근 <a class="header-anchor" href="#보관함-접근" aria-label="Permalink to &quot;보관함 접근&quot;">​</a></h2><p>관리자 메뉴 &gt; <strong>보관함</strong>으로 이동합니다.</p><h2 id="보관된-항목-조회" tabindex="-1">보관된 항목 조회 <a class="header-anchor" href="#보관된-항목-조회" aria-label="Permalink to &quot;보관된 항목 조회&quot;">​</a></h2><p>보관함에서 다음 유형의 항목을 확인할 수 있습니다:</p><table tabindex="0"><thead><tr><th>유형</th><th>설명</th></tr></thead><tbody><tr><td>프로젝트</td><td>보관된 프로젝트와 하위 토픽</td></tr><tr><td>토픽</td><td>보관된 토픽</td></tr><tr><td>채널</td><td>보관된 채널</td></tr></tbody></table><h2 id="보관-상태" tabindex="-1">보관 상태 <a class="header-anchor" href="#보관-상태" aria-label="Permalink to &quot;보관 상태&quot;">​</a></h2><p>보관된 프로젝트/토픽/채널은 <strong>읽기 전용</strong> 상태입니다:</p><ul><li>기존 메시지와 태스크를 조회할 수 있습니다.</li><li>새 메시지 작성, 태스크 생성/수정은 불가합니다.</li><li>구성원 변경, 설정 수정이 불가합니다.</li></ul><h2 id="복원" tabindex="-1">복원 <a class="header-anchor" href="#복원" aria-label="Permalink to &quot;복원&quot;">​</a></h2><p>보관된 항목을 다시 활성 상태로 복원할 수 있습니다. 복원 시 모든 읽기/쓰기 기능이 다시 활성화됩니다.</p><h2 id="영구-삭제" tabindex="-1">영구 삭제 <a class="header-anchor" href="#영구-삭제" aria-label="Permalink to &quot;영구 삭제&quot;">​</a></h2><p>보관된 항목을 영구 삭제하면 복원할 수 없습니다. 삭제 전 영향받는 데이터(토픽 수, 태스크 수, 메시지 수)가 표시됩니다.</p>',14)])])}const _=t(i,[["render",o]]);export{u as __pageData,_ as default};
